// 设置LCD显示文本
void update_lcd_text(const char* text) {
    if (ui_Lcd && ui_initialized) {
        lv_label_set_text(ui_Lcd, text);
    }
}

// 更新亮度显示
void ui_update_brightness_display(void) {
    if (ui_initialized) {
        char buffer[32];
        snprintf(buffer, sizeof(buffer), "亮度: %d%%", (led_brightness * 100) / 255);
        update_lcd_text(buffer);
    }
}

// 重置到就绪状态
void ui_reset_to_ready_state(void) {
    update_lcd_text("就绪");
}

// 应用亮度到所有LED
// ui.c
void apply_brightness_to_leds(void) {
    printf("亮度设置为: %d (%d%%)\r\n", led_brightness, (led_brightness * 100) / 255);
    
    // 根据当前模式立即更新LED显示
    switch(current_led_mode) {
        case 0: // 单色模式
            // 直接使用当前颜色重新设置所有LED
            for(u16 i = 0; i < Pixel_S1_NUM; i++) {
                rgb_SetColor(i, current_color);
            }
            rgb_SendArray();
            break;
            
        case 1: // 呼吸模式
            // 触发一次颜色更新（亮度会在 rgb_SetColor 中应用）
            {
                static uint8_t breath_idx = 0;
                RGBColor_TypeDef breath_colors[] = {RED, ORANGE, YELLOW, GREEN, SKY, BLUE, PURPLE};
                // 临时设置一个LED来触发亮度更新
                rgb_SetColor(0, breath_colors[breath_idx]);
                rgb_SendArray();
            }
            break;
            
        case 2: // 流水模式
            // 触发一次渐变更新
            smooth_color_gradient(Pixel_S1_NUM, 100);
            break;
            
        case 3: // 彩虹模式
            // 触发一次彩虹更新
            {
                static int rainbow_offset = 0;
                for(u8 i = 0; i < Pixel_S1_NUM; i++) {
                    rgb_SetColor(i, Colourful_Wheel(((i * 256 / Pixel_S1_NUM) + rainbow_offset) & 255));
                }
                rgb_SendArray();
            }
            break;
			case 4: // 音乐节奏模式：用ADC采集的音量控制LED
            LM_to_WS(); // 复用adc.c中已有的音量-LED映射函数
            break;
    }
}

// 设置颜色并更新状态
void set_color_and_update(RGBColor_TypeDef color, const char* color_name) {
    current_color = color;
    RGB_SetAll(Pixel_S1_NUM, color);
    update_lcd_text(color_name);
    current_led_mode = 0;
    printf("UI: 设置为%s\r\n", color_name);
}

