void ui_event_Slider1(lv_event_t * e)
{
    lv_event_code_t event_code = lv_event_get_code(e);
    lv_obj_t * target = lv_event_get_target(e);
    
    if(event_code == LV_EVENT_VALUE_CHANGED) {
        int32_t value = lv_slider_get_value(target);
        led_brightness = (uint8_t)value;
        
        // 立即应用亮度变化
        apply_brightness_to_leds();
        
        // 更新显示
        ui_update_brightness_display();
        
        printf("滑块值: %d, 亮度: %d\r\n", value, led_brightness);
    }
}

void ui_event_Dropdown1(lv_event_t * e)
{
    lv_event_code_t event_code = lv_event_get_code(e);
    lv_obj_t * target = lv_event_get_target(e);
    
    if(event_code == LV_EVENT_VALUE_CHANGED) {
		
        char buf[32];
        lv_dropdown_get_selected_str(target, buf, sizeof(buf));
        uint16_t selected = lv_dropdown_get_selected(target);
        
        // 关键：更新全局模式变量（与任务处理的case完全对应）
        current_led_mode = selected;
        
        // 切换模式时立即刷新LED初始状态
        switch(selected) {
            case 0: // 单色模式
                update_lcd_text("off");
                RGB_SetAll(Pixel_S1_NUM, current_color);  // 立即显示当前颜色
                printf("UI: 切换到单色模式（颜色：R=%d,G=%d,B=%d）\r\n", 
                       current_color.R, current_color.G, current_color.B);
                break;
                
            case 1: // 呼吸模式（多色循环）
                update_lcd_text("Breathing");
                printf("UI: 切换到呼吸模式（自动循环7色）\r\n");
                break;
                
            case 2: // 液体模式（流水渐变）
                update_lcd_text("Water Flow");
                printf("UI: 切换到液体模式（渐变流动）\r\n");
                break;
                
            case 3: // 向下流水模式（彩虹移动）
                update_lcd_text("Rainbow");
                printf("UI: 切换到向下流水模式（彩虹流动）\r\n");
                break;
                
 case 4: // 新增：音乐节奏模式
                update_lcd_text("Music Rhythm");
                printf("UI: 切换到音乐节奏模式，根据音量控制LED\r\n");
                // 初始化ADC采集（确保音频信号接入PA3）
                //Adc_PA3_Init(); 
                break;
            default: // 未知模式
                update_lcd_text("Unknown Mode");
                current_led_mode = 0;  //  fallback到单色模式
                RGB_SetAll(Pixel_S1_NUM, current_color);
                printf("UI: Unknown mode, fallback to Off\r\n");
                break;
        }
    }
}

